            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and grid[r][c] == 0:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in cardinal:
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and not outside[nr][nc]):
                outside[nr][nc] = True
                q.append((nr, nc))

    enclosed = {
        (r, c) for r in range(h) for c in range(w)
        if grid[r][c] == 0 and not outside[r][c]
    }

    # Shade just the inside layer of enclosed areas (including diagonal contact).
    outline_cells = set()
