        for dr, dc in around:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                out[r][c] = 3
                outline_cells.add((nr, nc))

    # Mark the outside halo adjacent to the enclosing outline.
    for r, c in outline_cells:
        for dr, dc in around:
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and outside[nr][nc]):
                out[nr][nc] = 2

